<?php if (!defined('ABSPATH')) { exit; } get_header(); ?>
<div class="site-layout reading-layout"><?php get_template_part('template-parts/rail'); ?><main id="main-content" class="reading-main">
<?php while (have_posts()): the_post(); $id = get_the_ID(); $repo = dh_repo(); $data = dh_meta('github'); $cats = get_the_category(); ?>
<nav class="breadcrumbs" aria-label="面包屑"><a href="<?php echo esc_url(home_url('/')); ?>">发现</a><span>/</span><?php if ($cats): ?><a href="<?php echo esc_url(get_category_link($cats[0])); ?>"><?php echo esc_html($cats[0]->name); ?></a><span>/</span><?php endif; ?><span>软件与灵感</span></nav>
<article <?php post_class('single-product'); ?>>
<header class="article-header"><div class="article-top"><?php dh_product_icon(); ?><div><span class="eyebrow"><?php echo dh_meta('license') ? esc_html(dh_meta('license')) . ' · 开放源码' : 'DISCOVER SOMETHING GOOD'; ?></span><h1><?php echo esc_html(dh_title()); ?></h1></div></div><?php if (dh_meta('summary')): ?><p class="article-summary"><?php echo esc_html(dh_meta('summary')); ?></p><?php endif; ?>
<div class="article-byline"><span><?php echo esc_html(get_the_author() ?: (dh_meta('submission_guest') ? '访客投稿' : dh_opt('brand'))); ?></span><span>发布于 <?php echo esc_html(get_the_date('Y-m-d')); ?></span><?php if (get_the_modified_date('Y-m-d') !== get_the_date('Y-m-d')): ?><span>更新于 <?php echo esc_html(get_the_modified_date('Y-m-d')); ?></span><?php endif; ?><?php dh_view_badge($id); ?><a href="#comments"><?php echo dh_icon('comment'); ?><?php echo esc_html(get_comments_number()); ?> 条讨论</a></div>
<div class="article-actions"><?php if ($repo): ?><a class="button" href="<?php echo esc_url($repo); ?>" target="_blank" rel="noopener"><?php echo dh_icon('github'); ?>GitHub 仓库 <?php echo dh_icon('external'); ?></a><?php endif; ?><?php if (dh_meta('website')): ?><a class="button <?php echo $repo ? 'secondary' : ''; ?>" href="<?php echo esc_url(dh_meta('website')); ?>" target="_blank" rel="noopener">访问官网 <?php echo dh_icon('external'); ?></a><?php endif; ?><?php if (dh_meta('download')): ?><a class="button secondary" href="<?php echo esc_url(dh_meta('download')); ?>" target="_blank" rel="noopener"><?php echo dh_icon('download'); ?>官方下载</a><?php endif; ?><?php dh_bookmark_button($id, true); ?><?php if (dh_opt('share')): ?><button class="button secondary" data-share data-url="<?php the_permalink(); ?>" data-title="<?php the_title_attribute(); ?>"><?php echo dh_icon('share'); ?>分享</button><?php endif; ?><?php dh_vote_button($id); ?></div>
<?php if (dh_meta('platform') || dh_meta('license') || dh_meta('version') || is_array($data)): ?><dl class="software-facts"><?php foreach (['platform' => '支持平台', 'license' => '开源协议', 'version' => '当前版本'] as $key => $label): if (dh_meta($key)): ?><div><dt><?php echo esc_html($label); ?></dt><dd><?php echo esc_html(dh_meta($key)); ?></dd></div><?php endif; endforeach; ?><?php if (is_array($data)): ?><div><dt>GitHub Stars</dt><dd><?php echo dh_icon('star'); ?> <?php echo esc_html(number_format_i18n($data['stars'])); ?></dd></div><?php endif; ?></dl><?php endif; ?>
</header>
<details class="toc" hidden><summary>内容导航</summary><nav aria-label="文章目录"></nav></details>
<div class="entry-content"><?php the_content(); wp_link_pages(['before' => '<nav class="pagination">', 'after' => '</nav>']); ?></div>
<?php if (is_array($data)): ?><p class="cache-note">GitHub 数据更新于 <?php echo esc_html(wp_date('Y-m-d H:i', $data['time'])); ?>，最新数据请以项目仓库为准。</p><?php endif; ?>
<?php the_tags('<div class="article-tags">', ' ', '</div>'); dh_ad('article'); ?>
<?php if (dh_opt('share')): ?><div class="share-bar"><?php if (dh_opt('share_caption') !== ''): ?><strong><?php echo esc_html(dh_opt('share_caption')); ?></strong><?php endif; ?><div><button class="button secondary" data-copy="<?php the_permalink(); ?>">复制链接</button><a class="button secondary" href="<?php echo esc_url('https://service.weibo.com/share/share.php?url=' . rawurlencode(get_permalink()) . '&title=' . rawurlencode(get_the_title())); ?>" target="_blank" rel="noopener nofollow">微博</a><a class="button secondary" href="<?php echo esc_url('https://connect.qq.com/widget/shareqq/index.html?url=' . rawurlencode(get_permalink()) . '&title=' . rawurlencode(get_the_title())); ?>" target="_blank" rel="noopener nofollow">QQ</a></div></div><?php endif; ?>
</article>
<nav class="post-navigation" aria-label="相邻文章"><?php previous_post_link('<div><small>上一篇</small>%link</div>'); next_post_link('<div><small>下一篇</small>%link</div>'); ?></nav>
<?php $related = new WP_Query(['posts_per_page' => 3, 'post_type' => 'post', 'post_status' => 'publish', 'category__in' => wp_get_post_categories($id), 'category__not_in' => array_intersect(wp_get_post_categories($id), dh_editorial_categories()) ? [] : dh_app_excluded_categories(), 'post__not_in' => [$id], 'ignore_sticky_posts' => true, 'no_found_rows' => true]); if ($related->have_posts()): ?><section class="related-posts"><div class="section-heading"><h2>你可能还会喜欢</h2></div><?php while ($related->have_posts()): $related->the_post(); get_template_part('template-parts/card'); endwhile; wp_reset_postdata(); ?></section><?php endif; ?>
<?php if (comments_open() || get_comments_number()) { comments_template(); } endwhile; ?>
</main><?php get_template_part('template-parts/sidebar'); ?></div><?php get_footer(); ?>
